What does this program print?

```swift
actor Counter {
    var value = 0
    func increment() -> Int {
        value += 1
        return value
    }
}
let counter = Counter()
await withTaskGroup(of: Void.self) { group in
    for _ in 1...50 {
        group.addTask { _ = await counter.increment() }
    }
}
print(await counter.value)
```
